@dataclass(frozen=True,slots=True)
class SemiconductorSurfaceDefinition:
    key:str; category:str; purpose:str; use_when:tuple[str,...]; avoid_when:tuple[str,...]=(); linked_hover:bool=False; spatial:bool=False
    def __post_init__(self):
        defaults={
            'spc':'when chart assumptions, subgroup structure, or baseline definition do not match the data',
            'capability':'when specification limits, measurement-system quality, or population definition are unknown',
            'wafer':'when coordinates are unavailable or spatial sampling is too sparse for the intended inference',
            'fdc':'when sensor semantics, recipe-step alignment, or event timing are unavailable',
            'rca':'as proof of causality without corroborating engineering evidence',
            'yield':'when numerator/denominator or bin definitions are inconsistent across populations',
            'reliability':'when failure/censoring semantics or exposure time are unknown',
            'doe':'for observational data that were not generated by a valid designed experiment',
        }
        default=defaults.get(self.category)
        if default and default not in self.avoid_when: object.__setattr__(self,'avoid_when',tuple(self.avoid_when)+(default,))

