SEMICONDUCTOR_SURFACE_REGISTRY:Mapping[str,SemiconductorSurfaceDefinition]=MappingProxyType({r[0]:SemiconductorSurfaceDefinition(*r) for r in _ITEMS})

def get_semiconductor_surface(key:str)->SemiconductorSurfaceDefinition:
    try:return SEMICONDUCTOR_SURFACE_REGISTRY[key]
    except KeyError as exc:raise KeyError(f'Unknown semiconductor analytical surface: {key}') from exc

class SemiconductorAnalyticalSurface:
    """Framework-neutral shared lifecycle/selection contract for semiconductor analytics."""
    def __init__(self,key:str,context:AnalysisContext,selections:SelectionBus, *, controller:AnalyticalPanelController|None=None)->None:
        self.definition=get_semiconductor_surface(key);self.context=context;self.selections=selections;self.controller=controller or AnalyticalPanelController();self._closed=False
    @property
    def key(self):return self.definition.key
    def loading(self,message:str|None=None):return self.controller.loading(message)
    def ready(self,message:str|None=None):return self.controller.ready(message)
    def empty(self,message:str|None='No data'):return self.controller.empty(message)
    def partial(self,reason:str,message:str|None=None):return self.controller.partial(reason,message)
    def stale(self,reason:str,message:str|None=None):return self.controller.stale(reason,message)
    def error(self,error:BaseException|str):return self.controller.error(error)
    def select(self,kind:SelectionKind,selection_id:str,values:Mapping[str,Any], *, mode:SelectionMutationMode=SelectionMutationMode.REPLACE,source:str|None=None):
        return self.selections.apply(Selection(kind,selection_id,values,source=source or self.key),mode=mode,source=source or self.key)
    def close(self):self._closed=True

